package com.vandorlabs.neoforge.infuser;
import com.vandorlabs.neoforge.rack.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.core.component.DataComponents;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.nbt.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.*;import net.minecraft.world.item.*;import net.minecraft.world.item.component.CustomData;import net.minecraft.world.level.block.Blocks;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.server.ServerStartedEvent;import net.neoforged.neoforge.event.tick.ServerTickEvent;
/** Actual installed solar furnace ticks, sided capabilities, strict owner NBT and cold continuation. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeInfuserRuntimeChecks {
 private static final BlockPos POS=new BlockPos(40,120,40);private static ServerLevel world;private static int checks;private static boolean ready;
 private static boolean enabled(){return Boolean.getBoolean("vandorlabs.infuserRuntimeChecks");}private static String phase(){return System.getProperty("vandorlabs.infuserRuntimePhase","runtime");}private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Infuser: "+why+diagnostics());}private static NativeInfuserEntity tile(){return (NativeInfuserEntity)world.getBlockEntity(POS);}private static Item matter(){return BuiltInRegistries.ITEM.get(ResourceLocation.parse("vandorlabs:programmable_matter_ingot"));}
 private static String diagnostics(){if(world==null)return " world=null";var raw=world.getBlockEntity(POS);var owner=raw instanceof NativeInfuserEntity t?t:null;return " available="+(owner!=null&&owner.available())+" inert="+(owner!=null&&owner.inert())+" sun="+(owner!=null&&owner.hasSunlight())+" day="+world.isDay()+" rain="+world.isRainingAt(POS.above())+" sky="+world.canSeeSky(POS.above())+" skylight="+world.getBrightness(net.minecraft.world.level.LightLayer.SKY,POS.above())+" directSkySourceY="+world.getChunkAt(POS).getSkyLightSources().getLowestSourceY(POS.getX()&15,POS.getZ()&15)+" motionHeight="+world.getHeight(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING,POS.getX(),POS.getZ())+" surfaceHeight="+world.getHeight(net.minecraft.world.level.levelgen.Heightmap.Types.WORLD_SURFACE,POS.getX(),POS.getZ())+" roof="+world.getBlockState(POS.above())+" progress="+(owner==null?-1:owner.progress())+" fuel="+(owner==null?-1:owner.fuelRemaining())+" catalyst="+(owner==null?"null":owner.getItem(1));}
 private static void sun(boolean day,boolean rain){world.setDayTime(day?6000:18000);world.setWeatherParameters(rain?0:20000,rain?6000:0,rain,false);world.setRainLevel(rain?1:0);world.updateSkyBrightness();}
 private static NativeInfuserEntity reset(){world.setBlock(POS.above(),Blocks.AIR.defaultBlockState(),3);world.setBlock(POS,NativeInfuserBindings.BLOCK.defaultBlockState(),3);world.removeBlockEntity(POS);var owner=new NativeInfuserEntity(POS,NativeInfuserBindings.BLOCK.defaultBlockState());owner.setLevel(world);world.setBlockEntity(owner);world.invalidateCapabilities(POS);sun(true,false);return owner;}
 private static void ticks(NativeInfuserEntity owner,int count){for(int i=0;i<count;i++)NativeInfuserEntity.tick(world,POS,owner.getBlockState(),owner);}
 private static NativeInfuserEntity reload(NativeInfuserEntity owner){var before=owner.saveWithFullMetadata(world.registryAccess());var next=new NativeInfuserEntity(POS,owner.getBlockState());next.setLevel(world);next.loadWithComponents(before,world.registryAccess());need(!next.inert(),"valid counters/private items reload");world.removeBlockEntity(POS);world.setBlockEntity(next);world.invalidateCapabilities(POS);return next;}
 private static ItemStack battery(){var stack=new ItemStack(NativeRackBindings.BATTERY);var data=new CompoundTag();data.putByteArray("InfuserPrivateBoard",new byte[257]);data.putString("InfuserProof","physical module only");stack.set(DataComponents.CUSTOM_DATA,CustomData.of(data));return stack;}
 @SubscribeEvent public static void start(ServerStartedEvent e){if(!enabled())return;try{world=e.getServer().overworld();world.setChunkForced(POS.getX()>>4,POS.getZ()>>4,true);world.getChunkAt(POS);world.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DAYLIGHT).set(false,e.getServer());world.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_WEATHER_CYCLE).set(false,e.getServer());ready=true;}catch(Throwable bad){fail(bad);}}
 @SubscribeEvent public static void tick(ServerTickEvent.Post e){if(!enabled()||!ready)return;ready=false;try{switch(phase()){case "runtime"->run();case "save"->save();case "read"->read();default->throw new IllegalArgumentException("Infuser phase");}System.out.println("[vandorlabs][infuser-runtime] "+phase()+" PASS checks="+checks+" physicalSolar/iron200/dust33/block300/module50RF/blockedOutput/nightTransfer/typedNBT/sidedAutomation/savedProcess");var server=world.getServer();world=null;server.halt(false);}catch(Throwable bad){fail(bad);}}
 private static void run(){var owner=reset();need(NativeInfuserEntity.fuelTicks(new ItemStack(Items.REDSTONE))==33&&NativeInfuserEntity.fuelTicks(new ItemStack(Blocks.REDSTONE_BLOCK))==300&&NativeInfuserEntity.fuelTicks(new ItemStack(Items.COAL))==0,"only Source catalysts with exact duration");need(NativeInfuserEntity.acceptsInput(new ItemStack(Items.IRON_INGOT))&&NativeInfuserEntity.acceptsInput(battery())&&!NativeInfuserEntity.acceptsInput(new ItemStack(Items.GOLD_INGOT)),"only iron and physical Battery Module inputs");owner.setItem(0,new ItemStack(Items.IRON_INGOT,2));owner.setItem(1,new ItemStack(Blocks.REDSTONE_BLOCK));world.setBlock(POS.above(),Blocks.STONE.defaultBlockState(),3);ticks(owner,15);need(!owner.hasSunlight()&&owner.progress()==0&&owner.fuelRemaining()==0&&owner.getItem(1).getCount()==1,"roof prevents work and catalyst consumption");world.setBlock(POS.above(),Blocks.GLASS.defaultBlockState(),3);need(owner.hasSunlight(),"transparent glass lens cover preserves Source direct sky behavior");world.setBlock(POS.above(),Blocks.AIR.defaultBlockState(),3);need(owner.hasSunlight(),"actual visible dry daytime sky");ticks(owner,100);need(owner.progress()==100&&owner.fuelRemaining()==200&&owner.getItem(1).isEmpty(),"one redstone block supplies300 working ticks");world.setBlock(POS.above(),Blocks.STONE.defaultBlockState(),3);ticks(owner,20);need(owner.progress()==100&&owner.fuelRemaining()==200,"roof pauses exact cook/catalyst counters");owner=reload(owner);need(owner.progress()==100&&owner.fuelRemaining()==200&&owner.getItem(0).getCount()==2,"paused reload retains input and counters");world.setBlock(POS.above(),Blocks.AIR.defaultBlockState(),3);ticks(owner,100);need(owner.getItem(2).is(matter())&&owner.getItem(2).getCount()==1&&owner.getItem(0).getCount()==1&&owner.progress()==0&&owner.fuelRemaining()==100,"exact200 working ticks produce one matter ingot");sun(false,false);ticks(owner,20);need(!owner.hasSunlight()&&owner.progress()==0&&owner.fuelRemaining()==100,"night pauses work/fuel");sun(true,true);ticks(owner,20);need(!owner.hasSunlight()&&owner.progress()==0&&owner.fuelRemaining()==100,"rain pauses exposed lens");world.setBlock(POS.above(),Blocks.STONE.defaultBlockState(),3);ticks(owner,2);world.setBlock(POS.above(),Blocks.AIR.defaultBlockState(),3);ticks(owner,1);need(!owner.hasSunlight()&&owner.progress()==0&&owner.fuelRemaining()==100,"immediate roof removal in actual rain cannot consume Matter/fuel while sky lighting is stale");world.setBlock(POS.above(),Blocks.GLASS.defaultBlockState(),3);need(owner.hasSunlight(),"transparent glass shelter preserves vanilla dry-lens behavior during rain");world.setBlock(POS.above(),Blocks.AIR.defaultBlockState(),3);sun(true,false);
  owner=reset();owner.setItem(0,new ItemStack(Items.IRON_INGOT));owner.setItem(1,new ItemStack(Items.REDSTONE));ticks(owner,33);need(owner.fuelRemaining()==0&&owner.progress()==33&&owner.getItem(1).isEmpty(),"dust supplies exactly33 working ticks");ticks(owner,8);need(owner.progress()==33,"no catalyst preserves partial cooking");owner.setItem(1,new ItemStack(Blocks.REDSTONE_BLOCK));ticks(owner,167);need(owner.getItem(2).is(matter())&&owner.getItem(0).isEmpty()&&owner.fuelRemaining()==133,"mixed catalyst continuation pays remaining167 ticks only");owner=reset();owner.setItem(0,new ItemStack(Items.IRON_INGOT));owner.setItem(1,new ItemStack(Blocks.REDSTONE_BLOCK));ticks(owner,20);owner.setItem(2,new ItemStack(matter(),64));ticks(owner,1);need(owner.progress()==0&&owner.fuelRemaining()==280,"blocked iron output resets cook progress without burning fuel");
  owner=reset();owner.setItem(0,battery());owner.setItem(1,new ItemStack(Blocks.REDSTONE_BLOCK));ticks(owner,199);need(NativeBatteryModule.energy(owner.getItem(0))==9950&&owner.getItem(2).isEmpty()&&owner.fuelRemaining()==101,"battery receives50RF per real catalyst tick");ticks(owner,1);need(NativeBatteryModule.energy(owner.getItem(0))==10000&&owner.fuelRemaining()==100,"200 charging ticks fill physical10k module");sun(false,false);ticks(owner,1);need(owner.getItem(0).isEmpty()&&NativeBatteryModule.energy(owner.getItem(2))==10000&&owner.fuelRemaining()==100&&NativeRackData.data(owner.getItem(2)).getByteArray("InfuserPrivateBoard").length==257,"full module moves output next tick at night without consuming more catalyst or private data");ticks(owner,8);need(owner.getItem(2).getCount()==1,"completed module publishes exactly one usable owner");
  owner=reset();owner.setItem(0,battery());owner.setItem(1,new ItemStack(Blocks.REDSTONE_BLOCK));owner.setItem(2,new ItemStack(matter(),64));ticks(owner,200);need(NativeBatteryModule.energy(owner.getItem(0))==10000&&owner.getItem(2).getCount()==64&&owner.fuelRemaining()==100,"blocked output does not stop partial battery charging");ticks(owner,7);need(NativeBatteryModule.energy(owner.getItem(0))==10000&&owner.fuelRemaining()==100,"full blocked module waits without fuel use");owner.removeItem(2,64);sun(false,false);ticks(owner,1);need(owner.getItem(0).isEmpty()&&NativeBatteryModule.energy(owner.getItem(2))==10000&&owner.fuelRemaining()==100,"full waiting module transfers to freed output at night");automation();legacy();malformed();held();}
 private static void automation(){var owner=reset();var up=world.getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,POS,Direction.UP);var down=world.getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,POS,Direction.DOWN);var side=world.getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,POS,Direction.WEST);var all=world.getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,POS,null);need(up!=null&&down!=null&&side!=null&&all!=null,"all furnace automation faces exposed");need(up.insertItem(0,new ItemStack(Items.IRON_INGOT,2),true).isEmpty()&&owner.getItem(0).isEmpty(),"top insertion simulation does not publish input");need(up.insertItem(0,new ItemStack(Items.IRON_INGOT,2),false).isEmpty()&&owner.getItem(0).getCount()==2,"top accepts iron into input");need(!up.insertItem(0,new ItemStack(Items.REDSTONE),false).isEmpty(),"top rejects catalyst");need(side.insertItem(0,new ItemStack(Items.REDSTONE),false).isEmpty()&&!side.insertItem(0,new ItemStack(Items.COAL),false).isEmpty(),"side accepts catalyst only");need(down.insertItem(0,new ItemStack(matter()),false).getCount()==1,"bottom refuses all insertion");owner.setItem(2,new ItemStack(matter(),2));need(down.extractItem(0,1,true).getCount()==1&&owner.getItem(2).getCount()==2,"bottom extraction simulation retains output");need(down.extractItem(0,1,false).getCount()==1&&owner.getItem(2).getCount()==1,"bottom extracts only output");need(down.getSlots()==2&&down.extractItem(1,1,false).isEmpty(),"Source bottom exposes fuel index but refuses catalyst extraction");need(up.extractItem(0,1,false).getCount()==1&&owner.getItem(0).getCount()==1&&side.extractItem(0,1,false).is(Items.REDSTONE),"Source top input and horizontal catalyst extraction remain available");owner.setItem(0,new ItemStack(Items.IRON_INGOT,2));need(!all.insertItem(2,new ItemStack(matter()),false).isEmpty()&&all.extractItem(0,1,false).getCount()==1,"unsided interface never inserts output, retains ordinary furnace extraction");var before=owner.saveWithoutMetadata(world.registryAccess());owner=reload(owner);need(up.insertItem(0,new ItemStack(Items.IRON_INGOT),false).getCount()==1,"retained stale handler refuses replacement owner");need(owner.getItem(0).getCount()==1,"stale handler cannot mutate replacement input");}
 private static CompoundTag legacyItem(int slot,String id,int count,CompoundTag custom){var row=new CompoundTag();row.putByte("Slot",(byte)slot);row.putString("id",id);row.putByte("Count",(byte)count);row.putShort("Damage",(short)0);if(custom!=null)row.put("tag",custom);return row;}
 private static void legacy(){var owner=reset();var raw=new CompoundTag();raw.putShort("BurnTime",(short)120);raw.putShort("CookTime",(short)80);raw.putShort("CookTimeTotal",(short)200);raw.putString("SourceUnknown","retained legacy field");var list=new ListTag();list.add(legacyItem(0,"minecraft:iron_ingot",2,null));list.add(legacyItem(1,"minecraft:redstone_block",1,null));list.add(legacyItem(2,"vandorlabs:programmable_matter_ingot",1,null));raw.put("Items",list);var source=raw.copy();var loaded=new NativeInfuserEntity(POS,owner.getBlockState());loaded.setLevel(world);loaded.loadWithComponents(raw,world.registryAccess());need(!loaded.inert()&&loaded.fuelRemaining()==120&&loaded.progress()==80&&loaded.getItem(0).getCount()==2&&loaded.getItem(1).is(Items.REDSTONE_BLOCK)&&loaded.getItem(2).is(matter()),"actual Source short furnace counters and id/Count/Damage rows migrate");need(source.equals(raw),"Source raw furnace data is never mutated");var modern=loaded.saveWithoutMetadata(world.registryAccess());var again=new NativeInfuserEntity(POS,owner.getBlockState());again.setLevel(world);again.loadWithComponents(modern,world.registryAccess());need(!again.inert()&&again.fuelRemaining()==120&&again.progress()==80&&again.saveWithoutMetadata(world.registryAccess()).getString("SourceUnknown").equals("retained legacy field"),"modern resave keeps Source counters/items/opaque fields");var batteryData=new CompoundTag();batteryData.putInt("BatteryEnergy",3850);batteryData.putString("InfuserLegacyProof","original private battery board");var batteries=new ListTag();batteries.add(legacyItem(0,"vandorlabs:battery_module",1,batteryData));raw.put("Items",batteries);raw.putShort("CookTime",(short)77);loaded.loadWithComponents(raw,world.registryAccess());need(!loaded.inert()&&NativeBatteryModule.energy(loaded.getItem(0))==3850&&NativeRackData.data(loaded.getItem(0)).getString("InfuserLegacyProof").equals("original private battery board"),"Source partially charged physical battery NBT migrates exactly");modern=loaded.saveWithoutMetadata(world.registryAccess());again.loadWithComponents(modern,world.registryAccess());need(!again.inert()&&ItemStack.matches(again.getItem(0),loaded.getItem(0)),"migrated battery modern component roundtrip");batteries.add(batteries.getCompound(0).copy());var duplicate=new NativeInfuserEntity(POS,owner.getBlockState());duplicate.setLevel(world);duplicate.loadWithComponents(raw,world.registryAccess());need(duplicate.inert(),"duplicate legacy Slot refuses ambiguous ownership");var saved=duplicate.saveWithoutMetadata(world.registryAccess());for(var key:raw.getAllKeys())need(Objects.equals(raw.get(key),saved.get(key)),"duplicate legacy original retained "+key);}
 private static void malformed(){var owner=reset();owner.setItem(0,new ItemStack(Items.IRON_INGOT));var valid=owner.saveWithoutMetadata(world.registryAccess());for(int kind=0;kind<14;kind++){var bad=valid.copy();var list=bad.getList("Items",Tag.TAG_COMPOUND);need(!list.isEmpty(),"valid modern saved inventory row");var row=list.getCompound(0);switch(kind){case 0->bad.putString("Items","bad");case 1->{var wrong=new ListTag();wrong.add(StringTag.valueOf("bad"));bad.put("Items",wrong);}case 2->row.remove("Slot");case 3->row.putInt("Slot",0);case 4->list.add(row.copy());case 5->row.getCompound("Stack").putInt("count",0);case 6->row.getCompound("Stack").putString("id","missing:unknown");case 7->row.putByte("Slot",(byte)7);case 8->bad.putInt("FuelRemaining",-1);case 9->bad.putInt("Progress",201);case 10->{var caps=new CompoundTag();caps.putInt("foreign:owned",21);bad.put("ForgeCaps",caps);}case 11->{var components=new CompoundTag();components.put("missing:unknown",new CompoundTag());bad.put("components",components);}case 12->{var attachments=new CompoundTag();attachments.put("missing:unknown",new CompoundTag());bad.put("neoforge:attachments",attachments);}case 13->bad.putInt("NativeInfuserSchema",2);}var staged=new NativeInfuserEntity(POS,owner.getBlockState());staged.setLevel(world);staged.loadWithComponents(bad,world.registryAccess());need(staged.inert(),"malformed owner remains inert kind="+kind);var kept=staged.saveWithoutMetadata(world.registryAccess());for(var key:bad.getAllKeys())need(Objects.equals(bad.get(key),kept.get(key)),"failed original retained exactly "+kind+"/"+key);var before=staged.saveWithoutMetadata(world.registryAccess());ticks(staged,2);need(before.equals(staged.saveWithoutMetadata(world.registryAccess())),"inert malformed owner tick cannot alter snapshot");}}
 private static void held(){var owner=reset();owner.setItem(0,battery());owner.setItem(1,new ItemStack(Blocks.REDSTONE_BLOCK));var before=owner.saveWithFullMetadata(world.registryAccess());var authority=new com.vandorlabs.neoforge.transfer.NativeTransferHolds.Authority(){final UUID id=UUID.randomUUID();public UUID operationId(){return id;}public boolean mutationArmed(){return true;}};try(var lease=com.vandorlabs.neoforge.transfer.NativeTransferHolds.freeze(world,authority,List.of(POS))){ticks(owner,3);need(before.equals(owner.saveWithFullMetadata(world.registryAccess())),"physical transfer hold suspends catalyst/module mutation");}ticks(owner,1);need(NativeBatteryModule.energy(owner.getItem(0))==50,"released hold permits exactly next ordinary work tick");}
 private static void save()throws java.io.IOException{var owner=reset();owner.setItem(0,battery());owner.setItem(1,new ItemStack(Blocks.REDSTONE_BLOCK));ticks(owner,60);need(NativeBatteryModule.energy(owner.getItem(0))==3000&&owner.fuelRemaining()==240,"saved physical partial charging baseline");world.setBlock(POS.above(),Blocks.STONE.defaultBlockState(),3);var saved=owner.saveWithoutMetadata(world.registryAccess());saved.putString("InfuserUnknown","retained across real restart");owner.loadWithComponents(saved,world.registryAccess());world.getServer().saveEverything(true,true,true);}
 private static void read(){var owner=tile();need(owner!=null&&!owner.inert()&&NativeBatteryModule.energy(owner.getItem(0))==3000&&owner.fuelRemaining()==240&&owner.progress()==60,"cold physical module/catalyst/cook counters retained");need(owner.saveWithoutMetadata(world.registryAccess()).getString("InfuserUnknown").equals("retained across real restart"),"opaque normal field survives process restart");ticks(owner,5);need(NativeBatteryModule.energy(owner.getItem(0))==3000&&owner.fuelRemaining()==240,"cold roof pause preserves physical item and catalyst");sun(true,false);world.setBlock(POS.above(),Blocks.AIR.defaultBlockState(),3);ticks(owner,140);need(NativeBatteryModule.energy(owner.getItem(0))==10000&&owner.fuelRemaining()==100,"remaining140 charge ticks reach exact full module");sun(false,false);ticks(owner,1);need(owner.getItem(0).isEmpty()&&NativeBatteryModule.energy(owner.getItem(2))==10000&&owner.getItem(2).getCount()==1&&NativeRackData.data(owner.getItem(2)).getByteArray("InfuserPrivateBoard").length==257,"cold continued charge publishes one full private component-bearing module at night");}
 private static void fail(Throwable bad){bad.printStackTrace();System.out.println("[vandorlabs][infuser-runtime] FAIL "+bad);var server=world==null?net.neoforged.neoforge.server.ServerLifecycleHooks.getCurrentServer():world.getServer();world=null;if(server!=null)server.halt(false);}
 private NativeInfuserRuntimeChecks(){}
}
